using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Reflection;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
class SafeKillChecks{
 static List<string> log=new List<string>();static void Test(string s,bool b){if(!b)throw new Exception(s);log.Add("PASS: "+s);}
 static NativeStopTarget Capture(Process p){return new NativeStopTarget{Id=p.Id,Started=p.StartTime.ToUniversalTime().Ticks,Path=p.MainModule.FileName,Name=p.ProcessName};}
 static object Call(object p,string name,params object[] args){return p.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(p,args);}
 [STAThread]static int Main(string[] args){Process a=null,b=null;Application app=null;PremiumPicker window=null;string root=args[0];Directory.CreateDirectory(root);try{
  var plan=NativeSessionStop.SelectIds(new[]{new NativeProcessRow{Id=1,Name="ChatGPT.exe"},new NativeProcessRow{Id=2,ParentId=1,Name="ChatGPT.exe"},new NativeProcessRow{Id=3,ParentId=2,Name="codex.exe"},new NativeProcessRow{Id=4,ParentId=1,Name="unrelated.exe"},new NativeProcessRow{Id=5,Name="codex.exe"}},new[]{1});
  Test("captured blockers include native worker descendants only",plan.SetEquals(new[]{1,2,3}));
  a=Process.Start(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"codex.exe"));b=Process.Start(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"codex.exe"));var target=Capture(a);Test("process identity matches PID, start time, executable and name",NativeSessionStop.Matches(a,target));
  target.Started++;NativeSessionStop.Stop(new[]{target});Test("changed start identity is never killed",!a.HasExited);target=Capture(a);target.Path+="wrong";NativeSessionStop.Stop(new[]{target});Test("changed executable path is never killed",!a.HasExited);
  NativeSessionStop.Stop(new[]{Capture(a)});Test("explicitly captured scratch native process is terminated",a.HasExited);Test("uncaptured process with same name is left running",!b.HasExited);NativeSessionStop.Stop(new[]{target});Test("already exited target is handled without error",true);b.Kill();b.WaitForExit();b.Dispose();b=null;
  var store=new ProfileStore(Path.Combine(root,"profiles"));app=new Application();System.Threading.SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());window=new PremiumPicker(store,false);window.Show();window.UpdateLayout();Call(window,"SetPending",store.State.Profiles[0].Id);var grid=(Grid)window.Content;var force=(Button)grid.FindName("ForceAndSwitch");Test("SafeKill button appears only for queued switching",force.Visibility==Visibility.Visible);
  var baseline=NativeApp.Running(store).Select(x=>x.Id).ToArray();bool cancelled=false;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(50)};timer.Tick+=(s,e)=>{foreach(Window d in app.Windows)if(d!=window&&d.IsVisible){Test("force quit warning mentions unsaved work",FindText(d).Contains("Unsaved work"));d.DialogResult=false;cancelled=true;timer.Stop();break;}};timer.Start();var task=(Task)Call(window,"ForceSwitch");var frame=new DispatcherFrame();task.ContinueWith(t=>window.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();timer.Stop();Test("confirmation cancellation prevents termination",cancelled&&baseline.All(id=>{try{return !Process.GetProcessById(id).HasExited;}catch{return false;}}));Test("controls reenable after cancellation",force.IsEnabled);((Button)grid.FindName("CancelSwitch")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Test("cancel queue hides SafeKill",force.Visibility==Visibility.Collapsed);
  window.Close();window=null;app.Shutdown();return 0;
 }catch(Exception ex){log.Add(ex.ToString());return 1;}finally{if(window!=null)window.Close();if(a!=null){if(!a.HasExited)a.Kill();a.Dispose();}if(b!=null){if(!b.HasExited)b.Kill();b.Dispose();}File.WriteAllLines(Path.Combine(root,"safekill-results.txt"),log);foreach(string s in log)Console.WriteLine(s);}}
 static string FindText(System.Windows.DependencyObject root){string s="";var text=root as TextBlock;if(text!=null)s+=text.Text;for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);i++)s+=FindText(System.Windows.Media.VisualTreeHelper.GetChild(root,i));return s;}
}
